---筛选按钮
---@class ScreenToggle
---@field TextContent                   	UnityEngine.UI.Text                     
---@field EventReceive                  	UnityEngine.RectTransform               
---@field ImgFrameNotSelect             	UnityEngine.RectTransform               
---@field ImgFrameSelect                	UnityEngine.RectTransform               
local ScreenToggle = Class('ScreenToggle')

------------- import --------------------
local KTool = CS.Engine.Lib.KTool
------------- import --------------------

function ScreenToggle:__init()
    ---@type integer
    self.ScreenType = nil
    ---@type integer
    self.condition = 0
    ---@type table<integer, integer[]>
    self.groups = nil
    ---@type fun(isOn:boolean):void
    self.onChangeCB = nil
end

function ScreenToggle:__delete()
    if self.__EventRestAction then
        Events.RemoveListener("EventUIScreenDialogsRest", self.__EventRestAction)
        self.__EventRestAction = nil
    end
    self.ScreenType = nil
    self.condition = nil
    self.controller = nil
    self.groups = nil
end

function ScreenToggle:Awake()
    KTool.SetActive(self.ImgFrameSelect, false)
    KTool.SetActive(self.ImgFrameNotSelect, true)
    SetButtonAction(self.EventReceive.gameObject, Bind(self, self.OnClickEventReceiveAction))

    self.__EventRestAction = Events.AddListener("EventUIScreenDialogsRest", Bind(self, self.OnEventRestAction))
end

---OnValueChange
---筛选toggle数值变化
---@param isOn boolean
function ScreenToggle:OnValueChange(isOn)
    --KTool.SetActive(self.OnObj, isOn)
    KTool.SetActive(self.ImgFrameSelect, isOn)
    -- KTool.SetActive(self.ImgFrameNotSelect, not isOn)
    -- self.TextContent.Status = isOn and 1 or 2
    CfUtils.SetUISwitchImage(self.ImgFrameNotSelect, isOn and 1 or 2)
    CfUtils.SetUISwitchText(self.TextContent, isOn and 2 or 1)
    if self.groups == nil then
        return
    end
    if isOn then
        --添加筛选选项
        if not isNull(self.groups[self.ScreenType]) then
            if table.indexof(self.groups[self.ScreenType], checkNumber(self.condition)) == false then
                table.insert(self.groups[self.ScreenType], checkNumber(self.condition))
            end
        else
            self.groups[self.ScreenType] = {}
            table.insert(self.groups[self.ScreenType], checkNumber(self.condition))
        end
    else
        --移除 选项
        if not isNull(self.groups[self.ScreenType]) then
            if table.indexof(self.groups[self.ScreenType], checkNumber(self.condition)) ~= false then
                table.removebyvalue(self.groups[self.ScreenType], checkNumber(self.condition), false)
            end
            if table.length(self.groups[self.ScreenType]) == 0 then
                self.groups[self.ScreenType] = nil
            end
        end
    end
end

---RefreshNode
---刷新筛选按钮
---@param type Constants.ScreenType
---@param cond integer @ 筛选数据id
---@param conditionName string @ 筛选选项名称
---@param groups table<integer, integer[]> 分组数
function ScreenToggle:RefreshNode(type, cond, conditionName, groups)
    self.groups = groups
    --设置筛选信息
    self.ScreenType = type
    self.condition = cond
    self.TextContent.text = conditionName
    --self.OnName.text = conditionName

    local isOn
    --判断当前
    if table.haskey(self.groups, checkNumber(type)) then
        if not isNull(self.groups[type]) then
            if table.indexof(self.groups[type], checkNumber(cond)) ~= false then
                --self.Toggle.isOn = true
                isOn = true
                self:OnValueChange(true)
            else
                isOn = false
                --self.Toggle.isOn = false
                self:OnValueChange(false)
            end
        end
    else
        isOn = false
        --self.Toggle.isOn = false
        self:OnValueChange(false)
    end

    self.isOn = isOn
end

function ScreenToggle:OnClickEventReceiveAction()
    self.isOn = not self.isOn
    self:OnValueChange(self.isOn)
    if self.onChangeCB then
        self.onChangeCB(self.isOn)
    end
end

function ScreenToggle:OnEventRestAction()
    local isOn = self.isOn
    if isOn then
        self:OnValueChange(false)
        self.isOn = false
    end
end

function ScreenToggle:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return ScreenToggle